const card = (key) => {
  const c = CLUSTER[key];
  return `<a href="${c.path}"><h3>${esc(c.card)}</h3><p>${esc(c.blurb)}</p></a>`;
};

const breadcrumb = (items) => ({
  '@type': 'BreadcrumbList',
  itemListElement: items.map(([name, path], i) => ({ '@type': 'ListItem', position: i + 1, name, item: SITE + path })),
});

