// Link-matrix checks: every related key exists, no self-links, every cluster page gets inbound links.
const inbound = Object.fromEntries(Object.keys(CLUSTER).map((k) => [k, 0]));
for (const g of GUIDES) {
  if (!CLUSTER[g.slug]) throw new Error(`Guide ${g.slug} missing from CLUSTER`);
  for (const r of g.related) {
    if (!CLUSTER[r]) throw new Error(`${g.slug} links to unknown cluster page ${r}`);
    if (r === g.slug) throw new Error(`${g.slug} links to itself`);
    inbound[r] += 1;
  }
  for (const [, href] of g.body.matchAll(/href="(\/[^"#]*)"/g)) {
    const file = href === '/' ? 'index.html' : href.endsWith('/') ? `${href.slice(1)}index.html` : `${href.slice(1)}.html`;
    const generated = Object.values(CLUSTER).some((c) => c.path === href) || href === '/guides/';
    if (!generated && !existsSync(join('website', file))) throw new Error(`${g.slug} has broken internal link ${href}`);
  }
}
for (const [k, n] of Object.entries(inbound)) {
  if (n < 2) throw new Error(`${k} has only ${n} related-card links from other guides (want 2+)`);
}

mkdirSync(OUT_DIR, { recursive: true });
writeFileSync(join(OUT_DIR, 'index.html'), hubPage());
for (const g of GUIDES) writeFileSync(join(OUT_DIR, `${g.slug}.html`), guidePage(g));
console.log(`Wrote ${GUIDES.length + 1} pages to ${OUT_DIR}`);
console.log('Inbound related-card links:', inbound);
